const customers=[{name:'佐藤先生',tag:'末班車之前',order:'醬油拉麵・不加蔥・麵偏硬',price:800,cash:1000,min:7,max:8.5,green:false,egg:false,opening:'不好意思，這個時間還能吃碗麵嗎？今天……有點不想這麼早回家。',response:['那我幫您倒杯熱茶。慢慢來。','今晚的湯，剛好還熱著。'],reply:['謝謝。光是有人說「慢慢來」，就覺得好多了。','那太好了。今天聽見的第一句好消息呢。'],story:'公司今天發了調動通知，下個月要去很遠的地方。女兒剛學會說「爸爸回來了」……我還不知道怎麼跟家裡說。',choices:['也許，她想聽的只是您會再回來。','要不要趁湯還熱，打通電話？'],ending:'嗯。我會跟她說，不管多遠，爸爸都會回來。老闆，謝謝你留著這盞燈。',memory:'「不管多遠，爸爸都會回來。」'},
{name:'小葵',tag:'離家後的第一碗麵',order:'味玉拉麵・加蔥・麵偏軟',price:900,cash:1000,min:10,max:11,green:true,egg:true,opening:'請問……一個人也可以坐嗎？我剛搬來附近，走著走著就聞到湯的味道。',response:['當然可以。這個位子，留給您。','歡迎來到河岸。想吃點熱的嗎？'],reply:['這句話好像媽媽。啊，不好意思，我不是說您老！','想。今天搬完家，才發現自己還沒好好吃飯。'],story:'我來這裡念設計。出門前跟媽媽說「終於自由了」，結果晚上買便當，突然好想她煮得軟軟的麵。',choices:['第一次離家，想家也是生活的一部分。','吃完傳張照片，讓她知道妳有好好吃飯。'],ending:'我傳了。她說：「加顆蛋啦，不要省。」……我明天也可以再來嗎？',memory:'「明天，也可以再來嗎？」'},
{name:'田中爺爺',tag:'她記得的味道',order:'醬油拉麵・加蔥・普通硬度',price:800,cash:2000,min:8.5,max:10,green:true,egg:false,opening:'這裡以前也有一台屋台。我和太太年輕時，常在這裡分一碗麵。',response:['那今晚也坐同樣的位置吧。','能聽您說說以前的河岸嗎？'],reply:['以前她總坐靠河那邊，說這樣吃麵才涼快。','那時候沒有這麼亮，可是每個人回家的腳步都很熟悉。'],story:'她去年走了。我總想再嚐一口那時的味道，卻連以前老闆的名字都忘了。只記得，那碗麵的蔥放得很多。',choices:['記得一起吃麵的時光，就沒有忘記。','我會記住，您的那碗要多放一點蔥。'],ending:'好，下次我再來。今天的麵不一樣，可是……也很溫暖。',memory:'「今天的麵不一樣，可是也很溫暖。」'}];
let state={phase:0,homeDone:false,homeLoaded:0,brothProfile:null,goodMeals:0,assembly:0,prep:0,cut:0,customer:0,step:'greet',money:0,served:0,stories:[],quality:[],day:1,change:0,cookElapsed:0,driveZ:65,parked:false},started=false,station='overview',accel=false,speed=0,dialogueOpen=false,last=performance.now(),totalTime=0,cameraGoal=null,keys={},drag=null,yaw=0,pitch=0,audioCtx,ambientGain,soundOn=true;
const spots={overview:{pos:[3.3,1.75,3.7],look:[0,1.6,.4]},prep:{pos:[1.2,1.72,2.9],look:[1.14,1.2,1.2]},stove:{pos:[-1.35,1.72,2.9],look:[-.9,1.5,1.1]},bowl:{pos:[.15,1.72,2.6],look:[.1,1.3,.8]},guest:{pos:[0,1.72,1.65],look:[0,1.7,-1.2]},cash:{pos:[1.9,1.72,1.45],look:[1.5,1.2,-.15]}};
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('toast').classList.remove('show'),3300)}
function initAudio(){if(audioCtx)return;try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();let buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.4;let src=audioCtx.createBufferSource();src.buffer=buffer;src.loop=true;let filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=900;ambientGain=audioCtx.createGain();ambientGain.gain.value=soundOn?.045:0;src.connect(filter).connect(ambientGain).connect(audioCtx.destination);src.start()}catch(e){}}
function tone(freq=440,duration=.1){if(!audioCtx||!soundOn)return;let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.045,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}
function save(silent=false){try{localStorage.setItem('yoru-yatai-save-v1',JSON.stringify({...state,player:state.phase>0||!state.homeDone?camera.position.toArray():null,view:[yaw,pitch],saved:true}));if(!silent)toast('這個夜晚已保存，可在同一瀏覽器繼續。')}catch(e){toast('無法儲存，瀏覽器可能封鎖本機儲存空間。')}}
let stored;try{stored=JSON.parse(localStorage.getItem('yoru-yatai-save-v1'))}catch(e){}if(stored?.saved)show('resumeBtn');
function go(name,instant=false){cameraGoal=null;if(instant){const p=state.player||[3.5,1.86,3.7];camera.position.set(...p);if(state.view){yaw=state.view[0];pitch=state.view[1];camera.rotation.set(pitch,yaw,0,'YXZ')}else{camera.lookAt(0,1.45,1.2);syncAngles()}}}
function syncAngles(){let e=new THREE.Euler().setFromQuaternion(camera.quaternion,'YXZ');yaw=e.y;pitch=e.x}
function needSpot(name){const p={prep:[1.2,1.2,1.2],stove:[-1,1.5,1.3],bowl:[.1,1.3,.9],guest:[0,1.7,-1.2],cash:[2,1.4,-.13]}[name];if(!p)return true;if(camera.position.distanceTo(new THREE.Vector3(...p))<(name==='guest'?4.6:2.5)){station=name;return true}toast('請親自走近'+({prep:'備料台',stove:'爐火',bowl:'盛碗台',guest:'客席',cash:'收銀'}[name])+'，場景標記會指引方向。');return false}
function getCustomer(){return customers[state.customer%3]}
function start(resume=false){initAudio();if(resume&&stored){state={...state,...stored};state.homeDone=stored.homeDone??true;if(state.phase===2)state.prep=2;if(state.phase===4&&state.step==='order')state.step='broth';if(state.step==='boiling'){state.step='noodle';state.cookElapsed=0}if(['pay','change'].includes(state.step)){state.step='pay';state.change=0}}started=true;grip=null;freePointer=null;keys={};hide('intro');hide('resumeBtn');show('hud');if(state.closed){setTimeout(()=>closeNight(),100)}if(state.phase===0&&!state.homeDone){cabin.visible=false;camera.position.set(...(resume&&state.player?state.player:[0,1.86,65]));camera.lookAt(2,1.3,63.2);syncAngles()}else if(state.phase===0){cabin.visible=true;camera.position.set(-6,1.7,state.driveZ);camera.lookAt(-6,1.65,state.driveZ-20);syncAngles()}else{go(state.phase<3?'overview':'guest',true)}renderState();save(true)}
$('startBtn').onclick=()=>start();$('resumeBtn').onclick=()=>start(true);$('brand').onclick=e=>{e.preventDefault();show('menu')};$('menuBtn').onclick=()=>{releaseWork();document.exitPointerLock?.();show('menu')};$('closeMenu').onclick=()=>hide('menu');$('saveBtn').onclick=()=>save();$('resetBtn').onclick=()=>{if(!started){toast('尚未開始新的夜晚。');return}if($('resetBtn').dataset.confirm!=='yes'){$('resetBtn').dataset.confirm='yes';$('resetBtn').textContent='再按一次，確認清除進度';return}localStorage.removeItem('yoru-yatai-save-v1');location.reload()};$('soundToggle').onchange=e=>{soundOn=e.target.checked;if(ambientGain)ambientGain.gain.value=soundOn?.045:0};

function visualState(){renderer.shadowMap.needsUpdate=true;cart.visible=!state.closed;cart.children.forEach(o=>{if(o.position.y>1.1&&!assemblies.includes(o)&&o!==equipment)o.visible=!started||state.phase>1||state.assembly>0});menuSign.visible=!started||state.phase>1||state.assembly>1;assemblies.forEach((m,i)=>m.visible=!state.closed&&(!started||state.phase>1||state.phase===1&&i<state.assembly));equipment.visible=!started||state.phase>=2&&!state.closed;warm.visible=lanternLight.visible=!state.closed&&(!started||state.phase>1||state.phase===1&&state.assembly>=3);steam.visible=state.phase>=2&&state.phase<5&&state.flame;customerRoot.visible=state.phase>=3&&state.phase<5;if(customerRoot.visible){if(customerRoot.userData.index!==state.customer){createCustomer(state.customer%3);customerRoot.userData.index=state.customer}}bowl.visible=state.phase===4&&state.step!=='greet'&&state.step!=='order';soup.visible=!['broth'].includes(state.step);noodles.visible=!['broth','noodle','boiling'].includes(state.step);pork.visible=swirl.visible=['green','egg','serve','talk','pay','change','bye'].includes(state.step);greens.visible=getCustomer().green&&['egg','serve','talk','pay','change','bye'].includes(state.step);eggs.visible=getCustomer().egg&&['serve','talk','pay','change','bye'].includes(state.step);bowl.position.set(.1,1.17,.9);if(['talk','pay','change','bye'].includes(state.step))bowl.position.set(0,1.29,-.3);prepFood.visible=state.prep<1;}
function renderState(){visualState();$('phaseIndex').textContent=String(state.phase+1).padStart(2,'0')+' / 06';$('phaseTitle').textContent=state.phase===0&&!state.homeDone?'從家裡出發':phases[state.phase];$('money').textContent=state.money.toLocaleString();$('served').textContent=state.served+' 碗・'+state.stories.length+' 段故事';$('clock').textContent=state.phase===0&&!state.homeDone?'18:15':state.phase===0?'18:40':state.phase===1?'18:55':state.phase===2?'19:10':state.phase===5?'23:40':['19:30','20:25','22:10'][state.customer%3];$('weather').textContent='第 '+state.day+' 夜・'+(state.phase===0&&!state.homeDone?'自宅車庫':state.phase===0?'自宅 → 河岸':'河岸通り');$('objective').textContent=state.phase===0&&!state.homeDone?'屋台已固定在車上。選今晚的湯味，再走到駕駛座出發。': [state.parked?'已抵達河岸。停妥車輛，開始今晚的工作。':'沿河岸前進，在亮燈的路段停車。W 加速、A/D 轉向、S 煞車。','展開車上的屋台，點起燈籠。今晚的準備不必從零搬裝。','食材已在家備妥。開火、試一口湯，就能迎接客人。',getCustomer().name+' 來到了屋台。先招呼他，再聽聽今晚想吃什麼。',getCustomer().name+' 的點單：'+getCustomer().order,'三位晚歸的人，都吃到了一碗熱麵。現在，該輪到你休息了。'][state.phase];let tasks=[];if(state.phase===1)tasks=['展開整座屋台','點亮燈籠、擺妥客席'].map((t,i)=>`<div class="${state.assembly>=(i===0?3:4)?'done':''}">${state.assembly>=(i===0?3:4)?'✓':'○'} ${t}</div>`);if(state.phase===2)tasks=[`<div>✓ 食材已在家備妥</div><div>${state.flame?'✓':'○'} 點火溫湯</div><div>○ 試湯開店</div>`];if(state.phase===4)tasks=[`<div>○ ${getCustomer().order}</div>`,`<div>¥${getCustomer().price} / 客人 ${state.customer+1} / 3</div>`];$('taskList').innerHTML=tasks.join('');if(state.phase===0&&state.homeDone){show('driveUI');hide('stations')}else{hide('driveUI');show('stations')}updateAction()}
function updateAction(){if(!started)return;let label='',help='';switch(state.phase){case 0:label=state.parked?'拉手煞車・下車':accel?'鬆開油門':'踩下油門';help=state.parked?'今夜的停靠處，就是這裡。':'也可按住 W 駕駛，S 減速；A / D 轉向。';break;case 1:label=['搬出並展開吧台','抬起支柱・架設屋頂','掛上暖簾・點亮燈籠','搬出圓凳・擺好客席'][state.assembly];help='每一次組裝，都是為今晚的客人留個位置。';break;case 2:label=state.prep===0?'切青蔥（'+state.cut+'/6）':state.prep===1?'切叉燒（'+state.cut+'/4）':state.prep===2?'開火・攪拌湯底':'洗碗・擺妥筷子';help=state.prep===2?'到爐火前，讓湯重新滾起來。':'到備料台，親手完成開店準備。';break;case 3:label='招呼今晚的客人';help='到客席，聽聽他的故事。';break;case 4:label={order:'記下這碗麵',broth:'舀入醬油湯底',noodle:'把麵放入沸水',boiling:'提起麵籃・瀝水',pork:'放上叉燒',green:getCustomer().green?'撒上青蔥':'這碗不加蔥・確認',egg:getCustomer().egg?'放上溏心蛋':'完成盛碗',serve:'端上這碗熱麵',talk:'聽他繼續說',pay:'收款・查看帳單',change:'找零給客人',bye:'送客・收拾空碗'}[state.step]||'繼續';help={broth:'爐火 → 盛碗台。先用熱湯暖好碗。',noodle:'前往爐火，下麵後時間就開始計算。',boiling:getCustomer().order+'。親手在喜歡的時間起麵。',pork:'到盛碗台，依照客人點單加入配料。',green:getCustomer().green?'記得他喜歡的那一把蔥。':'佐藤先生不吃蔥，這次就不加。',egg:getCustomer().egg?'媽媽說，吃飯不要省那一顆蛋。':'確認配料，讓這碗麵完整上桌。',serve:'前往客席，熱騰騰地端給客人。',pay:'到收銀處，確認收款與找零金額。',change:'點選錢幣，湊足應找金額。'}[state.step]||'每一位客人，都值得被好好聽見。';break;case 5:label='關火・清洗・收起屋台';help='把這個夜晚的溫暖，留在心裡。';break}$('actionBtn').textContent=label;$('actionHelp').textContent=help;$('actionBtn').disabled=dialogueOpen;}
function say(name,text,choices,tag=''){document.exitPointerLock?.();dialogueOpen=true;$('speaker').textContent=name;$('storyTag').textContent=tag;$('dialogueText').textContent=text;$('choices').innerHTML='';show('dialogue');hide('panel');for(let [label,fn]of choices){let b=document.createElement('button');b.textContent=label;b.onclick=()=>{hide('dialogue');dialogueOpen=false;fn?.();updateAction()};$('choices').append(b)}updateAction()}
function greet(){let c=getCustomer();say(c.name,c.opening,c.response.map((v,i)=>[v,()=>say(c.name,c.reply[i],[['請問今晚想吃什麼？',()=>{state.phase=4;state.step='order';renderState();say(c.name,`想要一碗${c.order}。麻煩你了。`,[['交給我，請稍等。',()=>{state.step='broth';renderState();save(true)}]],'今晚的點單')}]],c.tag)]),c.tag)}
let busy=false;async function timedAction(label,seconds,fn){seconds=.18;if(busy)return;busy=true;$('actionBtn').disabled=true;const start=performance.now();await new Promise(resolve=>{function tick(){let p=Math.min(1,(performance.now()-start)/(seconds*1000));$('actionBtn').textContent=label+' '+Math.round(p*100)+'%';if(p<1)requestAnimationFrame(tick);else resolve()}tick()});busy=false;fn();renderState();save(true)}
function action(){if(!started||dialogueOpen||busy||!$('menu').classList.contains('hidden'))return;initAudio();tone(310,.08);switch(state.phase){case 0:if(state.parked){cabin.visible=false;state.phase=1;accel=false;speed=0;camera.position.set(-5,1.86,6.3);camera.lookAt(3.1,1.0,2.7);syncAngles();go('overview');renderState();save(true)}else{accel=false;updateAction()}break;case 1:timedAction(['展開吧台','架好支柱','掛上暖簾','擺放圓凳'][state.assembly],1.2,()=>{state.assembly++;if(state.assembly===3)tone(660,.5);if(state.assembly===4){state.phase=2;toast('屋台搭好了。接下來，準備今晚的食材。');go('prep')}});break;case 2:if(state.prep===2){if(!needSpot('stove'))return;timedAction('攪拌湯底',3,()=>{state.prep++;go('prep');toast('湯底溫熱了，醬油香也醒了。')})}else{if(!needSpot('prep'))return;if(state.prep<2){state.cut++;tone(190,.06);if(state.cut>=(state.prep===0?6:4)){state.prep++;state.cut=0;toast(state.prep===1?'青蔥切好了。接著把叉燒切片。':'叉燒備好了，去爐火溫熱湯底。')}renderState();save(true)}else timedAction('沖洗與擺放',2,()=>{state.prep++;state.phase=3;go('guest');toast('暖簾已掛起。第一位客人走近了。')})}break;case 3:if(needSpot('guest'))greet();break;case 4:cookAction();break;case 5:closeNight();break}}
$('actionBtn').onclick=action;
function cookAction(){let c=getCustomer();switch(state.step){case 'order':state.step='broth';break;case 'broth':if(!needSpot('stove'))return;timedAction('舀湯入碗',1.5,()=>{state.step='noodle';toast('湯已入碗。留在爐火前，下麵。')});return;case 'noodle':if(!needSpot('stove'))return;state.step='boiling';state.cookElapsed=0;state.overcookWarn=false;show('cooking');$('cooking').querySelector('small').textContent=`客人偏好：${c.order.split('・').at(-1)} / 理想 ${c.min}–${c.max} 秒`;$('cooking').querySelector('.sweetSpot').style.left=c.min/20*100+'%';$('cooking').querySelector('.sweetSpot').style.width=(c.max-c.min)/20*100+'%';break;case 'boiling':if(!needSpot('stove'))return;hide('cooking');let t=state.cookElapsed,quality=t>=c.min&&t<=c.max?'剛剛好':t<c.min?'偏硬':'偏軟';state.quality[state.customer]=quality;state.step='pork';toast(`麵已起鍋（${t.toFixed(1)} 秒・${quality}）。去盛碗台放配料。`);go('bowl');break;case 'pork':if(!needSpot('bowl'))return;state.step='green';toast('叉燒放好了。');break;case 'green':if(!needSpot('bowl'))return;state.step='egg';toast(c.green?'撒上新鮮青蔥。':'確認不加蔥，記住客人的喜好。');break;case 'egg':if(!needSpot('bowl'))return;state.step='serve';toast(c.egg?'加上一顆溏心蛋，可以送餐了。':'拉麵完成，可以送餐了。');break;case 'serve':if(!needSpot('guest'))return;state.goodMeals=(state.goodMeals||0)+(state.quality[state.customer]==='剛剛好'?1:0)+((state.brothProfile||'light')===['light','rich','light'][state.customer%3]?1:0);state.step='talk';say(c.name,mealFeedback(),[['您剛剛說的事，願意多聊聊嗎？',()=>story()]],c.tag);break;case 'talk':if(!needSpot('guest'))return;story();break;case 'pay':if(!needSpot('cash'))return;openCheckout();return;case 'change':if(!needSpot('cash'))return;openCheckout();return;case 'bye':if(!needSpot('guest'))return;nextGuest();return}renderState();save(true)}
function story(){let c=getCustomer();say(c.name,c.story,c.choices.map(v=>[v,()=>say(c.name,c.ending,[['謝謝您，今晚慢慢走。',()=>{if(!state.stories.includes(c.memory))state.stories.push(c.memory);state.step='pay';renderState();go('cash');save(true)}]],c.tag)]),c.tag)}
function openCheckout(){state.step='change';state.change=0;hide('panel');renderState();save(true);toast('把抽屜裡的錢幣拖到找零盤。應找 ¥'+(getCustomer().cash-getCustomer().price)+'。')}
function nextGuest(){hide('panel');customerRoot.visible=false;state.customer++;state.step='greet';state.change=0;if(state.customer>=3){state.phase=5;go('overview');toast('最後一位客人離開了。河岸的風，也溫柔了一點。')}else{state.phase=3;go('guest');toast('收好空碗。另一位晚歸的客人坐了下來。')}renderState();save(true)}
