if(state.phase===4){switch(state.step){case 'order':return task('hold','記下點單',guestPoint,null,{reach:4.7});case 'broth':return task('transfer','從湯鍋舀湯，拖向碗中',potPoint,bowlPoint,{tool:'ladle'});case 'noodle':return task('transfer','把備好的麵拖入麵鍋',[-.5,1.3,1.95],[-.55,1.74,1.3]);case 'boiling':return task('lift','往上拖，提起麵籃',[-.55,1.74,1.3]);case 'pork':return task('transfer','夾起叉燒，放入碗中',[1.02,1.36,1.9],bowlPoint);case 'green':return getCustomer().green?task('transfer','把青蔥撒入碗中',[.63,1.34,1.9],bowlPoint):task('hold','這碗不加蔥，按住確認',bowlPoint,null,{seconds:.5});case 'egg':return getCustomer().egg?task('transfer','夾起溏心蛋，放入碗中',[1.42,1.36,1.9],bowlPoint):task('hold','檢查這碗麵，按住確認',bowlPoint,null,{seconds:.5});case 'serve':return carry?task('serve','把碗端到客人前方，按住放下',[0,1.48,-.3],null,{reach:3.5,seconds:.7}):task('pickupBowl','按住捧起這碗麵',bowlPoint,null,{seconds:.6});case 'talk':return task('hold','看向客人，繼續聽他說',guestPoint,null,{reach:4.7,seconds:.5});case 'pay':return task('hold','按住收下餐費 ¥'+getCustomer().cash,cashPoint,null,{seconds:.7});case 'change':return task('coins','把錢幣拖到找零盤，應找 ¥'+(getCustomer().cash-getCustomer().price),[1.65,1.45,.36],trayPoint);case 'bye':return carry?task('returnBowl','把空碗帶到水槽搓洗',sinkPoint):task('pickupEmpty','按住收起空碗',[0,1.5,-.3],null,{reach:3.5,seconds:.6})}}
