function projectPoint(a){camera.updateMatrixWorld();let p=V(a).project(camera),direction=V(a).sub(camera.position),forward=new THREE.Vector3();camera.getWorldDirection(forward);let front=direction.dot(forward)>0;return{x:(p.x+1)*innerWidth/2,y:(1-p.y)*innerHeight/2,front,on:front&&Math.abs(p.x)<.9&&Math.abs(p.y)<.85}}
