function aimed(t){let p=projectPoint(t.source);return p.front&&Math.hypot(p.x-innerWidth/2,p.y-innerHeight/2)<Math.min(170,innerWidth*.23)}
function hitPoint(e,a,r=75){let p=projectPoint(a);return p.front&&Math.hypot(e.clientX-p.x,e.clientY-p.y)<r}
function canWork(){return started&&!dialogueOpen&&!busy&&$('menu').classList.contains('hidden')}
