function releaseWork(e){freePointer=null;if(grip){const g=grip;if(['hold','pickup','place','pickupBowl','pickupEmpty','serve','homePickup','homeLoad','homeEnter','chooseBroth','lightLantern','tasteSoup','closeStall'].includes(g.t.mode)&&performance.now()-g.started>=(g.t.seconds||.7)*1000&&closeEnough(g.t)){completeGesture(g.t);drag=null;return}if(g.t.mode==='transfer'&&e&&hitPoint(e,g.t.target,90))completeGesture(g.t);else if(g.t.mode==='coins'&&e&&hitPoint(e,trayPoint,65)){checkoutCoin(g.coin);grip=null}else{grip=null;holdProgress=0;hand.visible=ladle.visible=false}}drag=null}
