addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;let key=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright','e',' '].includes(key))e.preventDefault();keys[key]=true;if(key==='e'&&!e.repeat){let t=getPhysicalTask();if(t&&!beginWork(null,t,true))toast(closeEnough(t)?'請把畫面中央對準標記，再按住 E。':'距離還太遠，請跟著標記親自走近。')}if(key==='escape'){hide('menu');hide('panel');releaseWork()}});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key.toLowerCase()==='e')releaseWork()});addEventListener('blur',()=>{keys={};releaseWork();if(started)save(true)});
